/**
 * Builds the CSS that exports embed, from the same tokens and report styles as the app, with the fonts inlined.
 * A test fails if the generated file drifts from its sources.
 *
 *   pnpm --filter @murphy/dashboard export-assets
 */
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const styles = (file: string) => path.join(ROOT, "src/styles", file);
const read = (file: string) => readFileSync(styles(file), "utf8");

const fontFace = (weight: number) => {
  const data = readFileSync(styles(`fonts/chivo-mono-latin-${weight}-normal.woff2`)).toString(
    "base64",
  );
  return `@font-face { font-family: "Chivo Mono"; font-style: normal; font-weight: ${weight}; font-display: swap; src: url("data:font/woff2;base64,${data}") format("woff2"); }`;
};

const STAMP = read("globals.css").split("@import")[0]!.trim();

const EXPORT_ONLY = `
.export { padding-block: var(--space-lg) var(--space-2xl); }
.export__foot { margin-top: var(--space-xl); padding-top: var(--space-md); border-top: var(--rule-bar) solid var(--color-rule); color: var(--color-muted); font-size: var(--text-label); }
`;

export function buildExportCss(): string {
  return [
    STAMP,
    read("tokens.css"),
    read("base.css"),
    ...[400, 500, 800].map(fontFace),
    read("report.css"),
    EXPORT_ONLY,
  ].join("\n");
}

export function buildAssetsModule(): string {
  return `// Generated by scripts/export-assets.ts. Do not edit.\nexport const EXPORT_CSS = ${JSON.stringify(buildExportCss())};\n`;
}

if (process.argv[1] && path.basename(process.argv[1]) === "export-assets.ts") {
  writeFileSync(path.join(ROOT, "src/export/generated/assets.ts"), buildAssetsModule());
}
